package io.odysz.reflect;

import java.util.ArrayList;
import java.util.HashMap;

import io.odysz.anson.Anson;

/**
 * The AST of an Anson type, the Java peer of anson.cmake's AnsonAst (reflect.h),
 * and semantics.py3's semanticshare.io.odysz.reflect.AnsonAst.
 * 
 * <p>Written by hand as *.ast.json for semantier_gen, or generated by anson.reflect's TypeScanner.</p>
 * 
 * @since 1.2.0
 */
public class AnsonAst extends Anson {
	public boolean isInt;
	public boolean isDouble;
	public boolean isEnum;
	public boolean isList;
	public boolean isMap;
	public boolean istring;
	public boolean isJsonable;
	public boolean isPortEnum;
	public boolean isVar;

	/** The target's type, e.g. io.odysz.semantic.tier.docs.Device */
	public String dataAnclass;

	/** The super class, e.g. io.odysz.anson.Anson */
	public String baseAnclass;

	/** {field name: field} */
	public HashMap<String, AnsonField> fields;

	public ArrayList<AnCtor> ctorsemantics;

	/** {enum constant: ordinal} */
	public HashMap<String, Integer> enums;

	/** Only one static string value is allowed in semantic-* ? */
	public String static_val;

	/////////////////// java only, generated by anson.reflect ////////////////////
	/** class, interface, enum, record or annotation */
	public String kind;

	/** e.g. ["public", "static", "abstract"], declared modifiers, for nested types too */
	public ArrayList<String> modifiers;

	/** Qualified names of the implemented interfaces */
	public ArrayList<String> interfaces;

	/**
	 * Qualified names of the types in the non-private API: super class, interfaces,
	 * type parameters' bounds, fields, ctors, methods and thrown exceptions,
	 * e.g. io.odysz.semantic.jprotocol.AnsonMsg.Port.
	 */
	public ArrayList<String> uses;

	public AnsonAst() { }

	/**
	 * @param dataAnclass
	 * @param baseAnclass
	 */
	public AnsonAst(String dataAnclass, String baseAnclass) {
		this.dataAnclass = dataAnclass;
		this.baseAnclass = baseAnclass;
		this.fields = new HashMap<String, AnsonField>();
		this.ctorsemantics = new ArrayList<AnCtor>();
	}
}
